import assert from 'node:assert/strict'
import { mkdirSync, mkdtempSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { test } from 'node:test'
import { checkCatalog, installCommand, loadCatalog, parseCask, parseFormula, readmeTable, renderReadme } from '../../docs/catalog.mjs'

const FORMULA = `# typed: false
# This file was generated by GoReleaser. DO NOT EDIT.
class Tool < Formula
  desc "A tool that does
one thing well.
"
  homepage "https://tool.example.org/"
  version "1.2.3"
  license "MIT"

  on_macos do
    if Hardware::CPU.intel?
      url "https://github.com/acme/tool/releases/download/v1.2.3/tool_1.2.3_darwin-amd64.tar.gz"
      define_method(:install) do
        bin.install "tool"
        bin.install "toolctl"
      end
    end
    if Hardware::CPU.arm?
      url "https://github.com/acme/tool/releases/download/v1.2.3/tool_1.2.3_darwin-arm64.tar.gz"
      define_method(:install) do
        bin.install "tool"
      end
    end
  end
  on_linux do
  end

  service do
    run macos: [opt_bin/"tool"]
  end

  test do
    system "#{bin}/tool", "version"
  end
end
`

const CASK = `cask "app" do
  version "0.3.1"
  url "https://github.com/acme/app/releases/download/v#{version}/app_#{version}_darwin-arm64.zip"
  name "App"
  desc "An app"
  homepage "https://app.example.org/"
  depends_on arch: :arm64
  depends_on macos: :tahoe
  app "App.app"
end
`

const ENTRY = { group: 'main', icon: 'icon.svg', title: 'Tool', tagline: 'Does one thing.', summary: 'Well.', site: 'https://tool.example.org/', status: 'active' }

function fixture({ items, formulae = { tool: FORMULA }, casks = { app: CASK } }) {
  const root = mkdtempSync(join(tmpdir(), 'tap-'))
  mkdirSync(join(root, 'Formula'))
  mkdirSync(join(root, 'Casks'))
  mkdirSync(join(root, 'docs/public'), { recursive: true })
  writeFileSync(join(root, 'docs/public/icon.svg'), '<svg/>')
  for (const [name, text] of Object.entries(formulae)) writeFileSync(join(root, `Formula/${name}.rb`), text)
  for (const [name, text] of Object.entries(casks)) writeFileSync(join(root, `Casks/${name}.rb`), text)
  const groups = [{ id: 'main', eyebrow: '01', title: 'Main', lead: 'Lead.' }]
  writeFileSync(join(root, 'docs/catalog.json'), JSON.stringify({ groups, items }))
  return root
}

const both = [
  { ...ENTRY, name: 'tool', kind: 'formula', local: 'http://tool.localhost:17999/', changelog: 'https://tool.example.org/changelog/v{version}/' },
  { ...ENTRY, name: 'app', kind: 'cask', title: 'App', site: 'https://app.example.org/' },
]

test('a Formula gives its version, platforms, binaries, service and check', () => {
  const f = parseFormula(FORMULA)
  assert.equal(f.version, '1.2.3')
  assert.equal(f.desc, 'A tool that does one thing well.')
  assert.equal(f.repository, 'acme/tool')
  assert.deepEqual(f.os, ['macOS', 'Linux'])
  assert.deepEqual(f.arch, ['arm64', 'x86_64'])
  assert.deepEqual(f.binaries, ['tool', 'toolctl'])
  assert.equal(f.service, true)
  assert.equal(f.check, 'tool version')
  assert.equal(parseFormula('test do\n    system "#{bin}/x --version"\n  end\n').check, 'x --version')
})

test('a Cask gives its version, app and requirements', () => {
  const c = parseCask(CASK)
  assert.equal(c.version, '0.3.1')
  assert.equal(c.appName, 'App')
  assert.equal(c.repository, 'acme/app')
  assert.deepEqual(c.arch, ['arm64'])
  assert.equal(c.minimum, '26')
  assert.deepEqual(c.apps, ['App.app'])
})

test('the catalog joins entries with packages, in the order of catalog.json', () => {
  const root = fixture({ items: [...both].reverse() })
  const { items, counts } = loadCatalog(root, { dates: false })
  assert.deepEqual(items.map((i) => i.name), ['app', 'tool'])
  assert.deepEqual(counts, { formula: 1, cask: 1 })
  const tool = items.find((i) => i.name === 'tool')
  assert.equal(tool.install, 'brew install --formula octolab/tap/tool')
  assert.equal(tool.changelog, 'https://tool.example.org/changelog/v1.2.3/')
  assert.equal(tool.release, 'https://github.com/acme/tool/releases/tag/v1.2.3')
  assert.equal(installCommand({ kind: 'cask', name: 'app' }), 'brew install --cask octolab/tap/app')
  assert.deepEqual(checkCatalog(root), [])
})

test('a package without an entry, and an entry without a package, fail the check', () => {
  const root = fixture({ items: [both[0], { ...ENTRY, name: 'gone', kind: 'formula' }] })
  const errors = checkCatalog(root)
  assert.ok(errors.some((e) => e.startsWith('Casks/app.rb: not in docs/catalog.json')), errors.join('\n'))
  assert.ok(errors.some((e) => e.startsWith('entry formula gone: no Formula/gone.rb')), errors.join('\n'))
})

test('the check reports bad fields, services and duplicates', () => {
  const items = [
    { ...both[0], local: undefined, site: 'http://tool.example.org/', status: 'new', changelog: 'https://x.example.org/notes/' },
    { ...both[1], icon: 'missing.svg', local: 'http://app.localhost:1/' },
    both[1],
  ]
  const errors = checkCatalog(fixture({ items }))
  for (const want of ['site must be an https:// URL', 'status must be one of', 'changelog must contain {version}', 'has a service block; set local',
    'icon docs/public/missing.svg does not exist', 'local is set, but Casks/app.rb has no service block', 'listed twice']) {
    assert.ok(errors.some((e) => e.includes(want)), `${want}\n${errors.join('\n')}`)
  }
})

test('the README block is generated without versions and replaced in place', () => {
  const root = fixture({ items: both })
  const table = readmeTable(root)
  assert.match(table, /\| \[Tool\]\(https:\/\/tool\.example\.org\/\) \| Does one thing\. \| `brew install --formula octolab\/tap\/tool` \|/)
  assert.doesNotMatch(table, /1\.2\.3/)
  const readme = 'intro\n<!-- catalog:begin -->\nold\n<!-- catalog:end -->\noutro\n'
  const next = renderReadme(root, readme)
  assert.ok(next.startsWith('intro\n<!-- catalog:begin (generated'))
  assert.ok(next.endsWith('<!-- catalog:end -->\noutro\n'))
  assert.equal(renderReadme(root, next), next)
  assert.throws(() => renderReadme(root, 'no block'), /no <!-- catalog:begin/)
})

test('a Cask with a binary and Linux, and a macOS release missing from the table', () => {
  const c = parseCask(`cask "cli" do\n  version "1.0.0"\n  url "https://github.com/acme/cli/releases/download/v#{version}/cli.zip"\n  binary "cli_1.0.0/bin/cli"\n  on_linux do\n  end\n  depends_on macos: :golden_gate\nend\n`)
  assert.deepEqual(c.binaries, ['cli'])
  assert.deepEqual(c.os, ['macOS', 'Linux'])
  assert.equal(c.minimum, 'Golden Gate')
})

test('open needs local and a command', () => {
  const root = fixture({ items: [{ ...both[0], open: 'tool service open' }, { ...both[1], open: ' ' }] })
  const errors = checkCatalog(root)
  assert.ok(errors.some((e) => e.includes('entry cask app: open must be the command')), errors.join('\n'))
  assert.ok(errors.some((e) => e.includes('entry cask app: open needs local')), errors.join('\n'))
  assert.ok(!errors.some((e) => e.includes('entry formula tool: open')), errors.join('\n'))
})
